 * Character-by-character position tracker over the input, split into
 * Unicode code points (so surrogate pairs count as one "character").
 */
export class Scanner {
  constructor(input) {
    this.cps = Array.from(input)
    this.i = 0
    this.line = 1
    this.col = 1
  }

  peek(k = 0) {
    return this.cps[this.i + k]
  }

  pos() {
    return { line: this.line, col: this.col }
  }

  atEnd() {
    return this.i >= this.cps.length
  }

  advance() {
    const c = this.cps[this.i]
    this.i++
    if (c === '\n') {
      this.line++
      this.col = 1
    } else if (c === '\t') {
      this.col = Math.floor((this.col - 1) / 4) * 4 + 5
    } else {
      this.col++
    }
    return c
  }
}

export class LexError extends Error {
  constructor(pos, reason) {
    super(reason)
    this.pos = pos
    this.reason = reason
  }
}
