const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = new Set(['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.'])

function isDecDigit(c) {
  return c !== undefined && c >= '0' && c <= '9'
}
function isHexDigit(c) {
  return c !== undefined && ((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))
}
function isBinDigit(c) {
  return c === '0' || c === '1'
}
function isOctDigit(c) {
  return c !== undefined && c >= '0' && c <= '7'
}
function isLetter(c) {
  return c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
}
function isIdentStart(c) {
  return isLetter(c) || c === '_'
}
function isIdentContinue(c) {
  return isLetter(c) || isDecDigit(c) || c === '_'
}

function err(pos, reason) {
  return new LexError(pos, reason)
}

function scanDigitRun(s, isDigit) {
  let text = ''
  if (!isDigit(s.peek())) return text
  text += s.advance()
  while (true) {
    if (s.peek() === '_' && isDigit(s.peek(1))) {
      text += s.advance()
      text += s.advance()
    } else if (isDigit(s.peek())) {
      text += s.advance()
    } else {
      break
    }
  }
  return text
}

function consumeTrailingContinuation(s) {
  let text = ''
  while (isIdentContinue(s.peek())) text += s.advance()
  return text
}

function scanIdent(s) {
  const pos = s.pos()
  let text = ''
  text += s.advance()
  while (isIdentContinue(s.peek())) text += s.advance()
  const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
  return { kind, line: pos.line, col: pos.col, text }
}

function scanNumber(s) {
  const pos = s.pos()
  let text = ''
  const first = s.peek()
  const second = s.peek(1)

  if (first === '0' && (second === 'x' || second === 'X')) {
    text += s.advance()
    text += s.advance()
    const digits = scanDigitRun(s, isHexDigit)
    if (digits === '') {
      text += consumeTrailingContinuation(s)
      throw err(pos, `invalid number ${text}`)
    }
    text += digits
  } else if (first === '0' && (second === 'b' || second === 'B')) {
    text += s.advance()
    text += s.advance()
    const digits = scanDigitRun(s, isBinDigit)
    if (digits === '') {
      text += consumeTrailingContinuation(s)
      throw err(pos, `invalid number ${text}`)
    }
    text += digits
  } else if (first === '0' && (second === 'o' || second === 'O')) {
    text += s.advance()
    text += s.advance()
    const digits = scanDigitRun(s, isOctDigit)
    if (digits === '') {
      text += consumeTrailingContinuation(s)
      throw err(pos, `invalid number ${text}`)
    }
    text += digits
  } else {
    text += scanDigitRun(s, isDecDigit)
    if (s.peek() === '.' && isDecDigit(s.peek(1))) {
      text += s.advance()
      text += scanDigitRun(s, isDecDigit)
    }
    if (s.peek() === 'e' || s.peek() === 'E') {
      let aheadOK = false
      if (isDecDigit(s.peek(1))) aheadOK = true
      else if ((s.peek(1) === '+' || s.peek(1) === '-') && isDecDigit(s.peek(2))) aheadOK = true
      if (aheadOK) {
        text += s.advance()
        if (s.peek() === '+' || s.peek() === '-') text += s.advance()
        text += scanDigitRun(s, isDecDigit)
      }
    }
  }

  if (isIdentContinue(s.peek())) {
    text += consumeTrailingContinuation(s)
    throw err(pos, `invalid number ${text}`)
  }

  return { kind: 'number', line: pos.line, col: pos.col, text }
}

function scanRawString(s) {
  const pos = s.pos()
  s.advance() // 'r'
  s.advance() // '"'
  let value = ''
  while (true) {
    if (s.atEnd()) throw err(pos, 'unterminated string')
    const c = s.advance()
    if (c === '"') break
    value += c
  }
  return { kind: 'rawstring', line: pos.line, col: pos.col, text: JSON.stringify(value) }
}

function scanString(s) {
  const pos = s.pos()
  s.advance() // opening quote
  let value = ''
  while (true) {
    const c = s.peek()
    if (c === undefined) throw err(pos, 'unterminated string')
    if (c === '"') {
      s.advance()
      break
    }
    if (c === '\n') {
      const p = s.pos()
      throw err(p, 'newline in string')
    }
    if (c === '\\') {
      const bpos = s.pos()
      s.advance() // backslash
      const esc = s.peek()
      if (esc === undefined) throw err(pos, 'unterminated string')
      if (esc === 'n') {
        value += '\n'
        s.advance()
      } else if (esc === 't') {
        value += '\t'
        s.advance()
      } else if (esc === 'r') {
        value += '\r'
        s.advance()
      } else if (esc === '\\') {
        value += '\\'
        s.advance()
      } else if (esc === '"') {
        value += '"'
        s.advance()
      } else if (esc === '0') {
        value += '\0'
        s.advance()
      } else if (esc === 'x') {
        s.advance() // 'x'
        const h1 = s.peek()
        if (h1 === undefined) throw err(pos, 'unterminated string')
        if (!isHexDigit(h1)) throw err(bpos, 'invalid escape \\x')
        s.advance()
        const h2 = s.peek()
        if (h2 === undefined) throw err(pos, 'unterminated string')
        if (!isHexDigit(h2)) throw err(bpos, 'invalid escape \\x')
        s.advance()
        value += String.fromCharCode(parseInt(h1 + h2, 16))
      } else if (esc === 'u') {
        s.advance() // 'u'
        const b1 = s.peek()
        if (b1 === undefined) throw err(pos, 'unterminated string')
        if (b1 !== '{') throw err(bpos, 'invalid escape \\u')
        s.advance()
        let hex = ''
        while (true) {
          const c2 = s.peek()
          if (c2 === undefined) throw err(pos, 'unterminated string')
          if (isHexDigit(c2)) {
            hex += s.advance()
            continue
          }
          break
        }
        if (hex.length === 0) throw err(bpos, 'invalid escape \\u')
        const closing = s.peek()
        if (closing === undefined) throw err(pos, 'unterminated string')
        if (closing !== '}') throw err(bpos, 'invalid escape \\u')
        s.advance()
        const cp = parseInt(hex, 16)
        if (cp > 0x10ffff) throw err(bpos, 'invalid escape \\u')
        value += String.fromCodePoint(cp)
      } else {
        throw err(bpos, `invalid escape \\${esc}`)
      }
    } else {
      value += s.advance()
    }
  }
  return { kind: 'string', line: pos.line, col: pos.col, text: JSON.stringify(value) }
}

function skipBlockComment(s) {
  const pos = s.pos()
  s.advance() // '/'
  s.advance() // '*'
  let depth = 1
  while (depth > 0) {
    if (s.atEnd()) throw err(pos, 'unterminated block comment')
    if (s.peek() === '/' && s.peek(1) === '*') {
      s.advance()
      s.advance()
      depth++
      continue
    }
    if (s.peek() === '*' && s.peek(1) === '/') {
      s.advance()
      s.advance()
      depth--
      continue
    }
    s.advance()
  }
}

function skipTrivia(s) {
  while (true) {
    const c = s.peek()
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      s.advance()
      continue
    }
    if (c === '/' && s.peek(1) === '/') {
      while (!s.atEnd() && s.peek() !== '\n') s.advance()
      continue
    }
    if (c === '/' && s.peek(1) === '*') {
      skipBlockComment(s)
      continue
    }
    break
  }
}

function scanPunct(s) {
  const pos = s.pos()
  const c0 = s.peek()
  const c1 = s.peek(1)
  const two = (c0 ?? '') + (c1 ?? '')
  if (PUNCT2.includes(two)) {
    s.advance()
    s.advance()
    return { kind: 'punct', line: pos.line, col: pos.col, text: two }
  }
  if (PUNCT1.has(c0)) {
    s.advance()
    return { kind: 'punct', line: pos.line, col: pos.col, text: c0 }
  }
  throw err(pos, `unexpected character ${c0}`)
}

export function tokenize(input) {
  const s = new Scanner(input)
  const tokens = []
  while (true) {
    skipTrivia(s)
    if (s.atEnd()) break
    const c = s.peek()
    let tok
    if (c === 'r' && s.peek(1) === '"') {
      tok = scanRawString(s)
    } else if (isIdentStart(c)) {
      tok = scanIdent(s)
    } else if (isDecDigit(c)) {
      tok = scanNumber(s)
    } else if (c === '"') {
      tok = scanString(s)
    } else {
      tok = scanPunct(s)
    }
    tokens.push(tok)
  }
  return tokens
}
"}

