import { readFileSync } from 'node:fs'
import { tokenize } from './lexer.js'
import { LexError } from './scanner.js'

const KINDS_ORDER = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }
  const mode = args[0]

  let input
  try {
    input = readFileSync(0, 'utf8')
  } catch {
    input = ''
  }

  let tokens
  try {
    tokens = tokenize(input)
  } catch (e) {
    if (e instanceof LexError) {
      process.stderr.write(`error: ${e.pos.line}:${e.pos.col}: ${e.reason}\n`)
      process.exit(2)
    }
    throw e
  }

  let out
  if (mode === 'tokens') {
    out = tokens.map((t) => `${t.line}:${t.col} ${t.kind} ${t.text}\n`).join('')
  } else {
    const counts = Object.fromEntries(KINDS_ORDER.map((k) => [k, 0]))
    for (const t of tokens) counts[t.kind]++
    const lines = KINDS_ORDER.map((k) => `${k} ${counts[k]}\n`)
    lines.push(`total ${tokens.length}\n`)
    out = lines.join('')
  }
  process.stdout.write(out)
  process.exit(0)
}

